"""Cross-validation tests for the three f(n) implementations."""

import itertools

import pytest

from bench_dp import (
    NAIVE_GUARD,
    f_memo,
    f_memo_safe,
    f_naive,
    f_roll,
)


def brute_force(n: int) -> int:
    """Ground truth by enumeration (only usable for tiny n)."""
    return sum(
        1
        for bits in itertools.product((0, 1), repeat=n)
        if all(not (bits[i] == bits[i + 1] == bits[i + 2]) for i in range(n - 2))
    )


def test_bases():
    assert f_roll(1) == 2
    assert f_roll(2) == 4
    assert f_memo(1) == 2
    assert f_memo(2) == 4


def test_brute_force_ground_truth_tiny():
    """The recurrence f(n) = f(n-1) + f(n-2) must match raw enumeration."""
    for n in range(1, 13):
        expected = brute_force(n)
        assert f_roll(n) == expected
        assert f_naive(n) == expected
        f_memo.cache_clear()
        assert f_memo_safe(n) == expected


def test_cross_validate_all_three_up_to_25():
    for n in range(1, 26):
        f_memo.cache_clear()
        values = {f_roll(n), f_memo_safe(n)}
        if n <= NAIVE_GUARD:
            values.add(f_naive(n))
        assert len(values) == 1, f"disagreement at n={n}: {values}"


def test_naive_guard_rejects_large_n():
    with pytest.raises(ValueError):
        f_naive(NAIVE_GUARD + 1)


def test_memo_vs_rolling_n_2000():
    f_memo.cache_clear()
    assert f_memo_safe(2000) == f_roll(2000)


def test_memo_vs_rolling_deep_without_crash():
    f_memo.cache_clear()
    # Must either agree or fail loudly as RecursionError -- never crash.
    try:
        assert f_memo_safe(50_000) == f_roll(50_000)
    except RecursionError:
        pytest.xfail("interpreter refused the recursion depth even on a big stack")


def test_f30_exact_value():
    f_memo.cache_clear()
    f30 = 2_692_538
    assert f_roll(30) == f30
    assert f_memo(30) == f30
    # (a) extended via (c): (a) matches (c) everywhere it is allowed to run,
    # which is what licenses using (c) for n = 30.
    for k in range(1, NAIVE_GUARD + 1):
        assert f_naive(k) == f_roll(k)

